const S={view:'work',object:'summary',saved:clone(initialConfig),drafts:clone(initialConfig),runtime:clone(initialConfig),savedRev:12,runtimeRev:12,editBase:12,runtimeKnown:true,phase:'clean',errors:{},failure:'none',paused:false,maintenance:false,wcsOnline:true,snapshotFresh:true,leftOnline:true,rightOnline:true,loginRequired:false,loggedIn:false,tray:false,scenario:'normal',reason:'',test:null,queryStatus:'idle',hasUnknown:false,changeLog:[],draftRetained:false,historySelection:0,historyFilters:{barcode:'',side:'all',result:'all',range:'today'},historyError:'',historyDateStart:'2026-10-20',historyDateEnd:'2026-10-20',historyAdvanced:false,aux:{},left:{status:'success',barcode:'000123456781',chute:'A-07',seq:128,time:'11:46:14'},right:{status:'success',barcode:'000123456782',chute:'B-12',seq:127,time:'11:46:12'}};
window.S=S;
function esc(v){return String(v??'').replace(/[&<>\x22']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\x22':'&quot;',"'":'&#39;'}[c]));}
const paths={box:'M3 7l9-4 9 4v10l-9 4-9-4V7zm0 0l9 4 9-4M12 11v10M7.5 5l9 4',work:'M3 4h8v16H3zM15 4h6v16h-6M6 8h2M6 12h2M17 8h2M17 12h2',history:'M3 12a9 9 0 109-9 9 9 0 00-7 3M3 3v5h5M12 7v5l3 2',settings:'M12 8a4 4 0 100 8 4 4 0 000-8M9 3l-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3H9',wrench:'M14 4a6 6 0 00-7 8l-4 5a2 2 0 003 3l5-5a6 6 0 008-7l-4 4-4-4 3-4',help:'M9 8a3 3 0 016 0c0 2-3 2-3 5M12 17v.1M21 12a9 9 0 11-18 0 9 9 0 0118 0',camera:'M4 6h12v12H4zM16 10l5-3v10l-5-3M8 3h4M9 10a2 2 0 100 4 2 2 0 000-4',server:'M4 3h16v7H4zM4 14h16v7H4zM7 6h.1M7 17h.1M11 6h6M11 17h6',check:'M4 12l5 5L20 6',alert:'M12 3l10 18H2L12 3M12 9v5M12 17v.1',arrow:'M4 12h16M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',folder:'M3 5h6l2 3h10v12H3V5',search:'M16 16l5 5M18 10a8 8 0 11-16 0 8 8 0 0116 0',close:'M5 5l14 14M19 5L5 19',download:'M12 3v12M7 10l5 5 5-5M3 16v5h18v-5',upload:'M12 16V4M7 9l5-5 5 5M3 16v5h18v-5',link:'M10 14l4-4M8 16l-2 2a4 4 0 01-6-6l5-5a4 4 0 016 0M16 8l2-2a4 4 0 016 6l-5 5a4 4 0 01-6 0',clock:'M12 6v6l4 2M21 12a9 9 0 11-18 0 9 9 0 0118 0',copy:'M8 8h13v13H8zM16 8V3H3v13h5',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4M8 11l3 3 5-6',pause:'M7 4v16M17 4v16',play:'M6 3l15 9-15 9V3'};
function icon(name,size=18){return `<svg width='${size}' height='${size}' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.7' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'><path d='${paths[name]||paths.box}'/></svg>`;}
function btn(label,action,type='secondary',attrs=''){return `<button type='button' class='button ${type}' data-action='${esc(action)}' ${attrs}>${label}</button>`;}
function tag(label,tone='neutral'){return `<span class='tag ${tone}'>${tone==='success'?icon('check',12):tone==='warning'||tone==='danger'?icon('alert',12):''}${esc(label)}</span>`;}
function note(tone,title,detail='',actionHTML=''){return `<div class='notice ${tone}' role='${tone==='danger'?'alert':'status'}'><span class='notice-icon'>${icon(tone==='success'?'check':tone==='warning'||tone==='danger'?'alert':'help',19)}</span><div class='notice-main'><strong>${title}</strong>${detail?`<p>${detail}</p>`:''}</div>${actionHTML?`<div class='actions'>${actionHTML}</div>`:''}</div>`;}
function section(title,body,sub=''){return `<section class='form-section'><h3>${title}</h3>${sub?`<div class='help'>${sub}</div>`:''}${body}</section>`;}
function field(label,key,value,help='',options={}){const id='f-'+key.replace(/[^a-z0-9]/gi,'-');const error=options.error||S.errors[key];return `<div class='field ${error?'error':''}'><label for='${id}'>${label}</label><div class='${options.unit?'input-wrap':''}'><input id='${id}' data-field='${esc(key)}' type='${options.type||'text'}' value='${esc(value)}' ${options.readonly?'readonly':''} ${options.disabled?'disabled':''} ${options.placeholder?`placeholder='${esc(options.placeholder)}'`:''} ${error?`aria-invalid='true' aria-describedby='${id}-error'`:''} ${options.numeric?`inputmode='numeric'`:''}>${options.unit?`<span class='unit'>${options.unit}</span>`:''}</div>${error?`<div class='error-text' id='${id}-error'>${icon('alert',14)}${esc(error)}</div>`:''}${help?`<div class='help'>${help}</div>`:''}</div>`;}
function selectField(label,key,value,options,help=''){const id='f-'+key.replace(/[^a-z0-9]/gi,'-');const error=S.errors[key];return `<div class='field ${error?'error':''}'><label for='${id}'>${label}</label><select id='${id}' data-field='${esc(key)}'>${options.map(o=>{const v=Array.isArray(o)?o[0]:o;return `<option value='${esc(v)}' ${value===v?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`;}).join('')}</select>${error?`<div class='error-text'>${icon('alert',14)}${esc(error)}</div>`:''}${help?`<div class='help'>${help}</div>`:''}</div>`;}
function diff(a,b){return Object.keys(a||{}).filter(k=>a[k]!==b?.[k]).map(k=>({key:k,before:b?.[k],after:a[k]}));}
function allChanges(a,b){return Object.keys(a).flatMap(o=>diff(a[o],b[o]).map(d=>({...d,object:o})));}
function dirty(){return allChanges(S.drafts,S.saved).length>0;}
function pending(){return S.savedRev!==S.runtimeRev||allChanges(S.saved,S.runtime).length>0||!S.runtimeKnown;}
function busy(){return ['validating','saving','applying'].includes(S.phase);}
function readDraft(o=S.object){return S.drafts[o]||{};}
function go(view,object){if(busy()){toast('当前操作正在完成，请稍候。');return;}if(dirty()&&!S.draftRetained||(typeof auxHasUnsaved==='function'&&auxHasUnsaved())){S.pendingNav={view,object};showUnsaved();return;}S.view=view;if(object)S.object=object;S.errors={};S.phase=dirty()?'dirty':pending()?'pending':'clean';render();document.querySelector('.workspace').scrollTop=0;}
function showUnsaved(){const changes=allChanges(S.drafts,S.saved);openDialog('离开前，如何处理本次修改？',`<p>${changes.length?`${changes.map(d=>objectNames[d.object]).filter((v,i,a)=>a.indexOf(v)===i).join('、')}有 ${changes.length} 项未保存修改。`:'当前任务有未保存内容。'}运行配置没有改变。</p>${changes.length?compareTable(changes):''}<p class='small muted' style='margin-top:16px'>保留草稿仅保留本次演示会话中的编辑；不会保存为配置修订，也不会投入运行。</p>`,btn('放弃本次修改','unsaved-discard')+btn('保留草稿并离开','unsaved-keep','primary')+btn('继续编辑','close-dialog'));}
let restoreFocus=null;
function openDialog(title,body,footer){restoreFocus=document.activeElement;document.getElementById('dialogs').innerHTML=`<div class='modal-backdrop'><section class='modal' role='dialog' aria-modal='true' aria-labelledby='dialog-title'><div class='modal-head'><h2 id='dialog-title'>${title}</h2>${btn(icon('close',18),'close-dialog','ghost',`aria-label='关闭对话框'`)}</div><div class='modal-body'>${body}</div><div class='modal-footer'>${footer}</div></section></div>`;document.getElementById('app').inert=true;const safe=document.querySelector('.modal-footer [data-action="close-dialog"]');(safe||document.querySelector('.modal button'))?.focus();}
function closeDialog(){document.getElementById('dialogs').innerHTML='';document.getElementById('app').inert=false;if(restoreFocus?.isConnected)restoreFocus.focus();}
let toastTimer;function toast(t){clearTimeout(toastTimer);document.getElementById('toast-area').innerHTML=`<div class='toast' role='status'>${esc(t)}</div>`;toastTimer=setTimeout(()=>document.getElementById('toast-area').innerHTML='',3300);}
function downloadText(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function compareTable(changes){return `<table class='table compare'><thead><tr><th style='width:26%'>对象 / 参数</th><th>变更前</th><th>变更后</th></tr></thead><tbody>${changes.map(d=>`<tr><td>${esc(objectNames[d.object]||d.object)}<br><span class='muted small'>${esc(fieldNames[d.key]||d.key)}</span></td><td class='mono'>${esc(d.key==='credential'?'已隐藏':d.before)}</td><td class='new mono'>${esc(d.key==='credential'?'已隐藏':d.after)}</td></tr>`).join('')}</tbody></table>`;}
function runtimeFooter(){
 if(S.view==='install')return `<div>${icon('box',16)} 安装任务</div><span>安装完成后还需首次配置与现场检查</span><span class='footer-right'>安装进度不代表作业就绪 · 模拟数据</span><button data-action='toggle-tray'>演示控制</button>`;
 const short=r=>({success:r.chute.length>12?'本次格口已取得':`格口 ${r.chute} · #${r.seq}`,waiting:'等待读码',processing:'正在取格口',unknown:'结果待核对',rejected:'本次被拒绝',offline:'相机中断'})[r.status];
 const left=S.snapshotFresh?(S.leftOnline?short(S.left):'相机中断'):'状态失效';const right=S.snapshotFresh?(S.rightOnline?short(S.right):'相机中断'):'状态失效';
 const run=S.runtimeKnown?(S.snapshotFresh?`运行 v${S.runtimeRev}`:`最后确认 v${S.runtimeRev}`):'运行版本待确认';
 const accepting=S.paused?'接收已暂停':!S.snapshotFresh||!S.runtimeKnown?'状态待核实':S.loginRequired&&!S.loggedIn?'等待操作员登录':S.hasUnknown||!S.wcsOnline||(!S.leftOnline&&!S.rightOnline)?'新包受阻':'接收中';
 const tone=(online,r)=>!S.snapshotFresh?'warn':!online||r.status==='rejected'?'bad':r.status==='unknown'?'warn':'';
 return `<div><span class='live-dot ${tone(S.leftOnline,S.left)}'></span>左位 · ${left}</div><div><span class='live-dot ${tone(S.rightOnline,S.right)}'></span>右位 · ${right}</div><button data-action='nav-diagnostics'><span class='live-dot ${S.wcsOnline?'':'bad'}'></span>WCS · ${S.wcsOnline?'连接可达':'连接中断'}</button><span class='footer-optional'>${accepting}</span><button class='footer-optional' data-action='nav-settings-summary'>${run}${pending()?` / 待生效 v${S.savedRev}`:''}</button><span class='footer-right'>模拟数据 · 2026-10-20 11:46 +08:00</span><button data-action='toggle-tray'>演示控制</button>`;
}
function render(){const root=document.getElementById('app');root.innerHTML=`<header class='titlebar'><div class='brand'><span class='brand-icon'>${icon('box',18)}</span>供包工作台<span class='title-context'>Sportmaster · 双投递位</span></div><div class='row'><span class='demo-mark'>设计原型 / 离线模拟</span><span class='window-actions' aria-hidden='true'><i>─</i><i>□</i><i>×</i></span></div></header><div class='shell'><nav class='sidebar' aria-label='主导航'><div class='station-name'><strong>示例工作站 17</strong><span>Sportmaster · 双投递位</span></div>${navButton('work','work','作业')}${navButton('history','history','作业记录')}${navButton('settings','settings','设备与设置')}${navButton('diagnostics','wrench','诊断与恢复')}<div class='sidebar-bottom'>${navButton('setup','check','首次配置')}${navButton('backup','folder','备份与迁移')}${navButton('support','help','帮助与支持')}<div class='side-foot'>双投递位供包<br>模拟环境 · 未连接现场</div></div></nav><main class='workspace' id='workspace'>${renderPage()}</main></div><footer class='status-footer'>${runtimeFooter()}</footer>`;renderTray();if(busy())root.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=true);}
function navButton(view,ic,label){return `<button class='nav-button ${S.view===view||(view==='settings'&&['install','advanced'].includes(S.view))?'active':''}' data-action='nav-${view}'>${icon(ic,19)}<span>${label}</span></button>`;}
function renderPage(){if(S.view==='work')return renderWork();if(S.view==='settings')return renderSettings();if(S.view==='history')return renderHistory();if(S.view==='diagnostics')return renderDiagnostics();if(typeof renderAux==='function')return renderAux(S.view);return '';}
function renderTray(){document.getElementById('tray').innerHTML=S.tray?`<aside class='prototype-tray'><div class='row between'><h3>演示控制</h3>${btn(icon('close',15),'toggle-tray','ghost',`aria-label='收起演示控制'`)}</div><p>仅改变本页模拟状态。无设备、WCS 或生产数据连接。</p>${selectField('作业场景','demo-scene',S.scenario,[['normal','左右均取得格口'],['waiting','等待扫码'],['processing','左位处理中 / 右位有结果'],['wcs-down','WCS 连接中断'],['camera-down','左相机中断 / 右位正常'],['unknown','结果未知 / 业务拒绝'],['stale','画面状态失效'],['long','长包裹号 / 长格口'],['login','已启用登录 · 未认证']])}${selectField('下一次操作的模拟结果','demo-failure',S.failure,[['none','成功'],['save','保存失败'],['apply','应用失败 · 已确认仍运行旧版本'],['unknown-runtime','应用失败 · 运行版本无法确认'],['conflict','关联冲突 / 修订已变化']])}<div class='actions'>${btn('参数错误演示','scene-camera-invalid','primary')}${btn('重置演示','reset-demo')}</div><p>更改作业场景保留参数编辑。重新打开文件会恢复初始模拟数据。</p></aside>`:'';}

