function workBanner(){if(!S.snapshotFresh)return note('danger','画面状态已失效 · 请勿依据旧格口继续投递','左右位的当前结果已隐藏。最后有效状态为 11:46:14；请保留现场包裹，先恢复状态读取。',btn('检查状态来源','nav-diagnostics'));if(!S.wcsOnline)return note('warning','WCS 连接中断 · 左右位的新包裹均受影响','左位本次请求结果待核对；右位已取得的结果仅对应当前所示包裹。不要重复扫码或重发请求。',btn('诊断 WCS','nav-diagnostics'));if(!S.leftOnline)return note('warning','左位相机连接中断 · 右位仍可继续作业','影响已确认仅限左相机。左位没有新的有效读码；右位仍按本次包裹结果作业。',btn('检查左相机','diagnose-left'));if(S.loginRequired&&!S.loggedIn)return note('warning','本站已启用操作员登录 · 等待认证后接收新包裹','这是已启用登录组件的场景；已有包裹结果保留，并单独标明。',btn('操作员登录','operator-login','primary'));if(S.paused)return note('neutral','新包裹接收已暂停','已有请求和结果继续保留；此操作不代表输送设备已停止。恢复前先确认阻断项已解除。',btn('检查并恢复接收','resume'));if(S.hasUnknown)return note('warning','左位有结果待核对 · 右位本次包裹被 WCS 拒绝','两个结果分别处理。查询原请求不会重新发送供包请求。',btn('查看异常','nav-diagnostics'));return '';}
function renderWork(){return `<div class='work'><div class='page-heading work-heading'><div><h1>作业</h1><p>左右位置固定对应现场投递位 · 以本次包裹结果作业</p></div><div class='actions'>${S.loginRequired&&S.loggedIn?tag('操作员：示例用户','neutral'):''}${btn(S.paused?icon('play',15)+' 检查并恢复接收':icon('pause',15)+' 暂停接收新包裹',S.paused?'resume':'pause')}</div></div>${workBanner()||`<div class='runtime-strip'><strong>${icon('check',16)} 可连续供包</strong><span class='status-sep'></span><span>左相机在线</span><span>右相机在线</span><span>WCS 连接可达</span><span class='spacer'></span><span class='muted'>当前运行配置 v${S.runtimeRev} · 模拟状态</span></div>`}<div class='lanes'>${renderLane('left')}${renderLane('right')}</div><section class='recent-section'><div class='recent-heading'><div class='row'><h2>最近结果</h2><p>历史记录 · 不作为当前包裹的投递依据</p></div>${btn('查看全部记录 '+icon('chevron',14),'nav-history','ghost')}</div><div class='panel flush'><table class='table recent-table'><thead><tr><th style='width:14%'>时间</th><th style='width:12%'>投递位</th><th style='width:32%'>包裹号</th><th style='width:24%'>本次处理结果</th><th>格口</th></tr></thead><tbody>${HISTORY.slice(0,3).map((r,i)=>`<tr data-action='record-${i}'><td class='mono'>${r.time}</td><td>${r.side==='left'?'左投递位':'右投递位'}</td><td class='mono'>${r.barcode}</td><td>${tag(r.result,r.tone)}</td><td class='mono'>${r.chute}</td></tr>`).join('')}</tbody></table></div></section><div class='sim-controls'><span>原型演示</span>${btn('模拟左位下一包','simulate-left','secondary')}${btn('模拟右位下一包','simulate-right','secondary')}<span class='sim-divider'></span><select aria-label='切换作业模拟场景' data-field='demo-scene'>${[['normal','正常结果'],['waiting','等待扫码'],['processing','左右不同状态'],['wcs-down','WCS 中断'],['camera-down','左相机中断'],['unknown','未知 / 拒绝'],['stale','状态失效'],['long','长内容'],['login','可选登录']].map(([v,l])=>`<option value='${v}' ${S.scenario===v?'selected':''}>${l}</option>`).join('')}</select><span class='sim-hint'>演示按钮不属于正式作业界面。正常扫码无需人工提交。</span></div></div>`;}
function renderLane(side){const r=S[side];const place=side==='left'?'左':'右';const online=side==='left'?S.leftOnline:S.rightOnline;let st=!S.snapshotFresh?'stale':!online?'offline':r.status;const map={success:['success','本次格口已取得','check'],waiting:['neutral','等待读码','camera'],processing:['info','已收到本次条码 · 正在请求 WCS','clock'],unknown:['warning','请求已发出 · 本次结果待核对','alert'],rejected:['danger','WCS 拒绝本次包裹','alert'],stale:['neutral','当前状态不可确认','alert'],offline:['warning','相机断线 · 等待恢复读码','alert']};const [tone,label,ic]=map[st]||map.waiting;let result;if(st==='success')result=`<div class='chute ${r.chute.length>8?'long':''}'>${esc(r.chute)}</div>`;else if(st==='processing')result=`<div class='chute processing'><span class='spinner'></span>正在获取格口</div>`;else result=`<div class='chute blank'>${({waiting:'等待下一包',unknown:'暂未确认格口',rejected:'本次不可投递',stale:'旧格口已隐藏',offline:'等待相机恢复'})[st]}</div>`;const instruction=({success:S.paused||S.loginRequired&&!S.loggedIn?'当前结果仅对应所示包裹':'按本次格口投递；下一包扫码后自动更新',waiting:'收到条码后自动请求 WCS',processing:'请等待本次结果，不重复扫码',unknown:'保留当前包裹；查询原请求结果',rejected:'保留当前包裹；查看拒绝原因',stale:'先恢复状态读取，再确认当前包裹',offline:'请勿在左位重复供包'})[st];const action=st==='unknown'?btn(S.queryStatus==='querying'?'正在核对…':'查询原请求','query-original','primary',S.queryStatus==='querying'?'disabled':''):st==='rejected'?btn('查看拒绝原因','rejection-detail'):['offline','stale'].includes(st)?btn('进入诊断',st==='offline'?'diagnose-left':'nav-diagnostics'):st==='success'?btn('本次详情',`current-${side}`,'ghost'):'';return `<section class='lane ${tone}' aria-label='${place}投递位'><div class='lane-head'><span class='lane-positionmark'>${side==='left'?'L':'R'}</span><span class='lane-pos'>${place}投递位</span><span class='tag ${online&&S.snapshotFresh?'neutral':'warning'}'>${!S.snapshotFresh?'状态失效':online?'相机在线':'相机中断'}</span></div><div class='lane-state'>${icon(ic,16)}${label}<span class='spacer'></span><span class='small mono'>${r.time}</span></div><div class='lane-body'><div class='result-label'>${st==='success'?'本次目标格口':'本次处理结果'}</div>${result}<div class='result-label'>${['waiting','offline'].includes(st)?'当前包裹':'本次包裹号'}</div><div class='barcode mono ${r.barcode.length>30?'long':''}'>${['waiting','offline'].includes(st)?'—':esc(r.barcode)}</div><div class='parcel-meta'><span>${['waiting','offline'].includes(st)?'尚无新读码':`本次序号 #${r.seq} · ${place}位读码`}</span><span>${st==='success'?'结果与本次条码绑定':'不显示上一包的格口'}</span></div></div><div class='lane-bottom'><span>${instruction}</span>${action}</div></section>`;}
function revisionBar(){const d=allChanges(S.drafts,S.saved).filter(x=>x.object===S.object).length;return `<div class='revision-bar'><div>编辑状态<strong>${d?`${d} 项未保存`:'未修改'}</strong></div><div class='${pending()?'rev-warning':''}'>已保存<strong>v${S.savedRev}${pending()?' · 待生效':''}</strong></div><div>实际运行<strong>${S.runtimeKnown?`v${S.runtimeRev}`:'待确认'}</strong></div></div>`;}
function settingsObjects(){return `<aside class='objects' aria-label='配置对象'><div class='group-label'>工作站</div>${objectButton('summary','work','当前配置与生效状态')}<div class='group-label'>设备与外部服务</div>${objectButton('left','camera','绑定：左投递位')}${objectButton('right','camera','绑定：右投递位')}${objectButton('wcs','server','用于左右投递位')}<div class='group-label'>关联设置</div>${objectButton('bindings','link','设备 → 位置 → 服务')}${objectButton('policies','settings','容量、超时与记录')}${objectButton('modules','box','安装、适用与启用')}<div class='object-foot'>配置对象始终可见<br>示例工作站 17 / Sportmaster</div></aside>`;}
function objectButton(o,ic,sub){const changed=diff(S.drafts[o],S.saved[o]).length;return `<button class='object-item ${S.object===o?'active':''}' data-action='object-${o}'>${icon(ic,19)}<span class='object-text'><strong>${objectNames[o]}${changed?' ·':''}</strong><small>${sub}</small></span></button>`;}
function renderSettings(){return `<div class='page-heading'><div><h1>设备与设置</h1><p>先选择配置对象，再编辑参数或检查连接</p></div><div class='actions'>${btn('查看修改记录','backup-history')}${btn(icon('help',15)+' 配置帮助','support-config','ghost')}</div></div><div class='settings-layout'>${settingsObjects()}<div class='settings-detail'>${S.object==='summary'?renderConfigSummary():S.object==='left'||S.object==='right'?renderCamera():S.object==='wcs'?renderWcs():S.object==='bindings'?renderBindings():S.object==='policies'?renderPolicies():renderModules()}</div></div>`;}
function renderConfigSummary(){let stateNotice=pending()?note(S.runtimeKnown?'warning':'danger',S.runtimeKnown?`已保存 v${S.savedRev}，当前仍运行 v${S.runtimeRev}`:'尚不能确认当前实际运行配置',S.runtimeKnown?'保存后的参数尚未投入运行。查看变更范围后，在受控维护时机应用。':'请先核实运行状态；不能把最近保存的配置当作运行配置。',btn('查看待生效变更','review-apply','primary')):note('success',`运行配置 v${S.runtimeRev} · 已保存配置一致`,'本页结果均为演示数据。运行版本在真实客户端应由运行端确认。');return `${stateNotice}<div class='panel flush'><div class='object-summary'><span class='obj-icon'>${icon('work',22)}</span><div><h2>示例工作站 17</h2><p>固定业务：Sportmaster · 左右相机 → WCS → 显示格口</p></div>${tag('配置示例','neutral')}</div>${[['left','左投递位','相机读码驱动 · 示例'],['right','右投递位','相机读码驱动 · 示例'],['wcs','左右位共用','WCS 集成 · 示例']].map(([o,pos,driver])=>`<div class='summary-row'><div><strong>${objectNames[o]}</strong><span class='muted'>${driver}</span></div><div>${pos}<br><span class='muted'>${o==='wcs'?'wcs-01':o==='left'?'CAM-L-021':'CAM-R-022'}</span></div><div>${tag(S.runtimeKnown?'运行 v'+S.runtimeRev:'运行待确认',S.runtimeKnown?'neutral':'warning')}<br><span class='muted'>${!S.runtimeKnown?`最后确认 v${S.runtimeRev}`:allChanges(S.saved,S.runtime).some(x=>x.object===o)?'有待生效修改':'与已保存值一致'}</span></div>${btn('配置参数',`object-${o}`)}</div>`).join('')}</div><div class='split' style='margin-top:18px'><div class='panel'><h3>工作站身份与数据</h3><div style='margin-top:12px'><div class='data-pair'><span>业务模块</span><strong>Sportmaster</strong></div><div class='data-pair'><span>运行模式</span><strong>离线模拟</strong></div><div class='data-pair'><span>工作站标识</span><code>reference-17</code></div><div class='data-pair'><span>数据根目录</span><code title='D:\\ImporterPC\\Data'>D:\\ImporterPC\\Data</code></div></div><div class='help small' style='margin-top:10px'>目录为设计示例。改变工作站身份或数据位置属于迁移任务。</div></div><div class='panel'><h3>当前适用能力</h3><div style='margin-top:12px'><div class='data-pair'><span>操作员登录</span><span>${S.saved.modules.login==='on'?'已启用（演示）':'未启用 · 不要求登录'}</span></div><div class='data-pair'><span>称重</span><span>本 Sportmaster 方案不启用</span></div><div class='data-pair'><span>传图</span><span>待需求与组件适用性确认</span></div><div class='data-pair'><span>PLC 下发</span><span>不属于本业务流程</span></div></div></div></div><div class='summary-links'>${[['setup','check','首次配置','新站准备、绑定与投入运行检查'],['backup','folder','备份与迁移','配置模板、修改记录和隔离恢复'],['install','box','安装与维护程序','程序目录、运行账户和组件安装'],['advanced','settings','高级与兼容配置','原始配置、旧版格式与恢复证据']].map(([view,ic,t,d])=>`<button class='summary-link' data-action='nav-${view}'>${icon(ic,22)}<span><strong>${t}</strong><small>${d}</small></span><span class='spacer'></span>${icon('chevron',16)}</button>`).join('')}</div>`;}
function objectHead(name,sub,ic='camera'){return `<div class='object-summary'><span class='obj-icon'>${icon(ic,22)}</span><div><h2>${name}</h2><p>${sub}</p></div>${tag(S.object==='wcs'?'左右位共用':'编辑对象已锁定','neutral')}</div>${revisionBar()}`;}
function phaseNotice(){if(S.phase==='validating')return note('info',`${objectNames[S.object]} · 正在校验`,'检查字段格式、设备绑定和整站配置关联。');if(S.phase==='saving')return note('info','正在保存为整站待生效修订','本次编辑将合并到当前配置；运行值保持不变。');if(S.phase==='save-failed')return note('danger','保存失败 · 输入已保留',`模拟保存失败。已保存与运行配置均未被本次操作覆盖；可重试保存或复制诊断信息。`,btn('重试保存','save'));if(S.phase==='conflict')return note('danger','配置版本发生冲突 · 本次修改未保存','另一处修改已经更新保存基线。先比较冲突，再合并；不能自动覆盖已有修改。',btn('查看冲突','compare-conflict'));if(S.phase==='applying')return note('info','正在应用配置 · 新包裹接收已暂停','正在执行受控重启并读取运行端确认；请勿关闭程序。');if(S.phase==='apply-failed')return note('danger',S.runtimeKnown?`应用失败 · 已确认仍运行 v${S.runtimeRev}`:'应用失败 · 当前运行版本待确认',S.runtimeKnown?`待生效 v${S.savedRev} 已保留。新包裹接收仍暂停；确认旧配置可以工作后再恢复。`:'不能确认新旧配置的运行归属。保持暂停，先诊断并读取运行状态。',btn('诊断应用失败','nav-diagnostics'));if(S.phase==='invalid')return note('danger',`有 ${Object.keys(S.errors).length} 项需要修正 · 其他输入已保留`);return '';}
function renderCamera(){const o=S.object,d=readDraft(),position=o==='left'?'左':'右';return `<div class='panel flush'>${objectHead(`${position}位相机`,`${position}投递位 · ${d.identity} · 示例工作站 17`)}<div class='object-content'>${phaseNotice()}${section('设备与绑定',`<div class='form-grid'>${field('设备名称',o+'.name',d.name,'用于对象列表与诊断信息。')}${field('设备标识',o+'.identity',d.identity,'离线示例；正式身份需通过真实 SDK 核验。',{readonly:true})}</div><div class='scope-line' style='margin-top:15px'>${icon('camera',17)}<span>读码驱动 · 演示适配器</span><span class='spacer'></span>${btn('选择驱动','choose-driver','ghost')}${btn('查看绑定','object-bindings','ghost')}</div>`)}${section('连接参数',`<div class='form-grid'>${field('设备地址',o+'.address',d.address,'示例：192.0.2.21；保留完整地址。')}${field('连接端口',o+'.port',d.port,'地址 / 端口仅用于演示本次编辑与校验。',{numeric:true})}</div><div class='row between' style='margin-top:15px'><span class='help small'>测试采用当前编辑值，不保存、不应用、不发送包裹。</span>${btn(S.test?.phase==='testing'?'<span class="spinner small"></span> 正在检查':icon('link',15)+' 测试连接','test-camera','secondary',S.test?.phase==='testing'?'disabled':'')}</div>${renderTestInline()}`,'此处为演示驱动的字段示例；实际字段、单位和可用范围由对应驱动定义。')}<details><summary>技术标识与生效影响</summary><div class='data-pair'><span>内部来源标识</span><code>sportmaster.camera.${o}</code></div><div class='data-pair'><span>实例编号</span><code>${o==='left'?'reader.1':'reader.2'}</code></div><p class='help small'>保存范围为整站关联修订。本次仅合并所示编辑；当前设计按受控重启生效，不能据此假设支持单相机热更新。</p></details></div></div>${saveBar()}`;}
function renderWcs(){const d=readDraft();return `<div class='panel flush'>${objectHead('WCS 格口服务','左右投递位共用 · 服务实例 wcs-01','server')}<div class='object-content'>${phaseNotice()}<div class='wcs-layout'><div>${section('连接与访问',`${field('服务名称','wcs.name',d.name,'用于异常提示和诊断定位。')}${field('服务地址','wcs.url',d.url,'设计示例；正式路径与协议由 WCS 集成确认。')}${field('访问凭据','wcs.credential',d.credential,'正式客户端按组件要求隐藏敏感值。',{readonly:true})}<div class='form-grid'>${field('调用超时','wcs.timeout',S.drafts.policies.timeout,'来自运行与记录，作用范围待核实。',{readonly:true,unit:'ms'})}${field('集成实例','wcs.instance','wcs-01','对应本工作站左右投递位。',{readonly:true})}</div>`,'此处连接字段为设计示例，截图未显示真实 WCS 参数。')}<div class='actions'>${btn(S.test?.phase==='testing'?'<span class="spinner small"></span> 正在检查':icon('link',15)+' 测试连接','test-wcs','primary',S.test?.phase==='testing'?'disabled':'')}${btn('运行策略','object-policies','ghost')}</div><p class='help small' style='margin-top:10px'>使用当前编辑地址 · 不保存、不应用、不发送供包请求。</p></div><aside class='wcs-test-panel'><h3>本次连接检查</h3>${S.test?.object==='wcs'?renderTestInline():`<div class='empty' style='padding:25px 10px'>${icon('link',26)}<h3>尚未测试当前参数</h3><p>点击测试连接后，分别查看目标地址、传输连接和业务验证范围。</p></div>`}<details><summary>如何理解测试结果</summary><p class='help small'>传输可达不能证明 WCS 业务响应有效。业务验证必须依据集成明确支持的安全检查或受控实机验收。</p></details></aside></div><details><summary>协议与技术标识</summary><div class='data-pair'><span>原请求查询</span><span>仅在集成明确声明支持时可用</span></div><div class='data-pair'><span>请求字段与合同版本</span><span>由本 WCS 集成定义</span></div><p class='help small'>维护面板可查完整配置原文；主表单不要求用户编辑协议 JSON。</p></details></div></div>${saveBar()}`;}
function renderTestInline(){if(!S.test||S.test.object!==S.object)return '';if(S.test.phase==='testing')return note('info',`正在测试${objectNames[S.object]}`,'只检查当前编辑目标；运行配置未改变。');if(S.test.phase==='failed')return `<div style='margin-top:14px'>${note('danger',`${objectNames[S.object]}连接未建立`,'模拟结果：地址格式有效，传输连接被拒绝。请检查地址、端口以及服务是否正在监听。',btn('定位连接参数','focus-connection','ghost'))}<div class='test-summary'><div class='row between'><span>本次测试目标</span><code>${esc(S.test.target)}</code></div><div class='row between'><span>已验证：地址格式</span>${tag('通过','success')}</div><div class='row between'><span>传输连接</span>${tag('拒绝连接','danger')}</div><div class='row between'><span>读取设备 / WCS 业务响应</span><span class='muted'>未执行</span></div><div class='row between'><span>当前编辑值 · 测试未写入配置</span>${btn('复制技术详情','copy-test','ghost')}</div></div></div>`;return `<div style='margin-top:14px'>${note('success','传输连接可达 · 模拟结果','本次未采集设备数据，也未验证真实 WCS 业务。测试不保存、不应用配置。',btn('查看分层结果','test-detail','ghost'))}</div>`;}
function saveBar(){const changes=diff(readDraft(),S.saved[S.object]||{});const all=changes;const pendingChanges=allChanges(S.saved,S.runtime);let title=changes.length?`${changes.length} 项未保存修改`:pending()?`已保存 v${S.savedRev} · 待生效`:'没有未保存修改';if(busy())title=({validating:'正在校验配置',saving:'正在保存配置',applying:'正在应用配置'})[S.phase];return `<div class='save-bar' id='save-bar'><div><strong id='save-status'>${title}</strong><p>编辑基线 v${S.editBase} · 保存会生成整站关联修订</p></div><div class='actions'>${btn('撤销本次编辑','undo','secondary',!all.length||busy()?'disabled':'')}${btn('校验','validate','secondary',busy()?'disabled':'')}${all.length?btn('保存为待生效修订','save','primary',busy()?'disabled':''):pending()?btn('查看并应用','review-apply','primary',busy()?'disabled':''):btn('保存','save','primary','disabled')}</div></div>`;}

function renderBindings(){const d=readDraft();const choices=[['cam-left','左位相机 · CAM-L-021'],['cam-right','右位相机 · CAM-R-022']];return `<div class='panel flush'>${objectHead('投递位绑定','一次编辑两路的对应关系 · 保存前统一检查','link')}<div class='object-content'>${phaseNotice()}${note('info','先配置设备实例，再绑定到现场位置','设备名称用于识别；设备标识用于确认具体相机。修改绑定不会改变设备身份。')}<div class='binding-row'><div class='binding-place'><span class='lane-positionmark'>L</span>左投递位</div>${selectField('读码设备','bindings.left',d.left,choices,'确认设备标签与现场左侧一致。')}<span class='muted'>${icon('arrow',20)}</span><div><div class='muted small'>格口服务</div><strong>WCS 格口服务</strong><p class='muted small'>共用服务 wcs-01</p></div></div><div class='binding-row'><div class='binding-place'><span class='lane-positionmark'>R</span>右投递位</div>${selectField('读码设备','bindings.right',d.right,choices,'同一相机不能重复绑定两个位置。')}<span class='muted'>${icon('arrow',20)}</span><div><div class='muted small'>格口服务</div><strong>WCS 格口服务</strong><p class='muted small'>共用服务 wcs-01</p></div></div><div class='scope-line' style='margin-top:16px'><span>共用格口服务：WCS 格口服务 · wcs-01</span><span class='spacer'></span>${btn('服务参数','object-wcs','ghost')}</div><div class='scope-line' style='margin-top:20px'>${icon('work',17)}<span>业务流程：相机读码 → 请求 WCS → 按左右位显示格口</span></div><div class='actions' style='margin-top:18px'>${btn('查看左位相机','object-left','ghost')}${btn('查看右位相机','object-right','ghost')}${btn('检查绑定关系','validate','secondary')}</div></div></div>${saveBar()}`;}
function renderPolicies(){const d=readDraft();return `<div class='panel flush'>${objectHead('运行与记录','工作站范围 · 使用截图样例值，正式范围待核实','settings')}<div class='object-content'>${phaseNotice()}${section('作业处理',`<div class='form-grid'>${field('输入队列容量','policies.queue',d.queue,'原图样例 64；需要核实满队列时的处理策略。',{numeric:true})}${field('调用超时','policies.timeout',d.timeout,'原图样例 1500 ms；调用对象与在途请求影响需核实。',{numeric:true,unit:'ms'})}${field('作业容量','policies.capacity',d.capacity,'保留原字段；计数对象与正式上限待实现核实。',{numeric:true})}${field('常驻历史条数','policies.history',d.history,'同库归档不释放磁盘；不能将此参数当作磁盘清理。',{numeric:true})}</div>`,'这些数值不是推荐值或默认值。参数含义不确定时保留名称与原值，不擅自改变现场策略。')} ${section('生效与维护',`<div class='data-pair'><span>变更范围</span><strong>当前 Sportmaster 工作站</strong></div><div class='data-pair'><span>生效方式</span><span>保存后，在受控维护时机重启应用</span></div><div class='data-pair'><span>历史数据</span><span>修改容量不代表删除已有记录</span></div><div class='actions' style='margin-top:14px'>${btn('备份与恢复','nav-backup')}${btn('查看版本与高级配置','nav-advanced','ghost')}</div>`)}<details><summary>显示偏好 · 与运行参数分开</summary><div class='row between'><div><strong class='small'>减少动画</strong><p class='help small'>立即改变本原型的过渡效果，不修改运行修订。</p></div><label class='checkbox-row'><input type='checkbox' data-field='preference-motion' ${S.reduceMotion?'checked':''}>减少动态效果</label></div><p class='help small'>实际触摸控件尺寸、系统缩放和高对比支持需要 Windows 实机验证。</p></details></div></div>${saveBar()}`;}
function renderModules(){return `<div class='panel flush'>${objectHead('已安装组件','安装、适用性、启用与运行健康分别判断','box')}<div class='object-content'>${phaseNotice()}${note('info','按当前业务展示适用能力','以下为原型示例库存。正式驱动包、版本和授权资格需从交付介质读取。')}<table class='table'><thead><tr><th style='width:25%'>组件 / 驱动</th><th style='width:23%'>安装或来源</th><th style='width:28%'>当前使用情况</th><th>操作</th></tr></thead><tbody><tr><td><strong>相机读码</strong><br><span class='muted small'>演示适配器</span></td><td>${tag('示例组件','neutral')}</td><td>已绑定左、右位<br><span class='muted small'>读码能力需真实 SDK 验证</span></td><td>${btn('设备参数','object-left','ghost')}</td></tr><tr><td><strong>WCS 集成</strong></td><td>${tag('示例组件','neutral')}</td><td>左右位共用</td><td>${btn('服务参数','object-wcs','ghost')}</td></tr><tr><td><strong>操作员登录</strong></td><td>演示登录组件</td><td>${S.drafts.modules.login==='on'?tag('待按配置生效','info'):'未启用 · 不要求登录'}</td><td>${selectField('是否启用','modules.login',S.drafts.modules.login,[['off','不启用'],['on','启用（演示）']])}</td></tr><tr><td><strong>称重</strong></td><td>截图有参考提供者</td><td>本方案不启用<br><span class='muted small'>适用性待需求确认</span></td><td>${btn('不适用','none','secondary',`disabled title='本 Sportmaster 方案未配置称重任务'`)}</td></tr><tr><td><strong>图片上传</strong></td><td>旧版策略可见</td><td>未启用<br><span class='muted small'>不新增包裹图片预览</span></td><td>${btn('查看旧版配置','nav-advanced','ghost')}</td></tr></tbody></table><div class='row between' style='margin-top:18px'><span class='help small'>安装成功不代表已绑定、已启用或设备健康。</span>${btn(icon('box',16)+' 安装组件','install-component')}</div><details><summary>维护认证与技术清单</summary><p class='help small'>保留现有维护认证入口；查看和编辑草稿不要求操作员强制登录。保存与应用的认证策略由现行安全约束确认。</p><div class='actions'>${btn('查看组件技术清单','component-json','ghost')}${btn('验证维护身份（模拟）','maintenance-auth','ghost')}</div></details></div></div>${saveBar()}`;}
function filteredHistory(){return HISTORY.filter(r=>(!S.historyFilters.barcode||r.barcode.includes(S.historyFilters.barcode))&&(S.historyFilters.side==='all'||S.historyFilters.side===r.side)&&(S.historyFilters.result==='all'||S.historyFilters.result===r.result));}
function renderHistory(){const f=S.historyFilters,rows=filteredHistory(),selected=HISTORY[S.historySelection],sel=rows.includes(selected)?selected:null;return `<div class='page-heading'><div><h1>作业记录</h1><p>查询固定结果快照，选择一条记录查看对应包裹和请求</p></div><div class='actions'>${btn(icon('download',16)+' 导出当前结果','export-history','secondary',rows.length?'':'disabled title="当前没有可导出的记录"')}</div></div><div class='panel history-filters'>${field('包裹号','history.barcode',f.barcode,'保留前导零',{placeholder:'输入完整或部分包裹号'})}${selectField('时间范围','history.range',f.range,[['today','今天'],['24h','最近 24 小时'],['custom','自定义'],['all','不限时间']])}${selectField('投递位','history.side',f.side,[['all','全部位置'],['left','左投递位'],['right','右投递位']])}${selectField('处理结果','history.result',f.result,[['all','全部结果'],['格口已取得','格口已取得'],['业务拒绝','业务拒绝'],['已核对原请求','已核对原请求']])}<div class='actions' style='padding-bottom:21px'>${btn('查询','query-history','primary')}${btn('更多','history-advanced','ghost')}</div></div>${S.historyFilters.range==='custom'||S.historyAdvanced?`<div class='panel' style='margin-bottom:16px'><div class='form-grid three'>${field('开始日期（包含）','history-start',S.historyDateStart,'按所示时区解释输入',{type:'date',error:S.historyError||undefined})}${field('结束日期（包含整天）','history-end',S.historyDateEnd,'转为次日零点之前，保持原结束不含语义',{type:'date'})}${field('时区','history-timezone','Asia/Shanghai · UTC+08:00','高级原始时间与请求标识可在所选记录中查看',{readonly:true})}</div>${S.historyError?note('danger',S.historyError,'查询尚未更新，已有记录与其他输入保留。'):''}<details><summary>精确时间 / 原请求标识</summary><p class='help small'>正式实现保留开始（含）、结束（不含）的完整偏移时间及原请求 ID。原型仅演示日期范围校验，不模拟完整历史数据库。</p>${field('原请求 ID（演示筛选）','history.request','REQ-L-0128','将作为精确查询条件；不改变原请求。')}</details></div>`:''}<div class='history-layout'><div class='panel flush'><table class='table'><thead><tr><th style='width:14%'>时间</th><th style='width:12%'>位置</th><th style='width:30%'>包裹号</th><th style='width:28%'>结果</th><th>格口</th></tr></thead><tbody>${rows.length?rows.map(r=>{const i=HISTORY.indexOf(r);return `<tr class='${i===S.historySelection?'selected':''}' data-action='select-record-${i}' tabindex='0'><td class='mono'>${r.time}</td><td>${r.side==='left'?'左位':'右位'}</td><td class='mono'>${r.barcode}</td><td>${tag(r.result,r.tone)}</td><td class='mono'>${r.chute}</td></tr>`;}).join(''):`<tr><td colspan='5'><div class='empty'>${icon('search',28)}<h3>没有符合条件的记录</h3><p>核对包裹号、时间和投递位。可以清除筛选后再查询。</p>${btn('清除筛选','clear-history')}</div></td></tr>`}</tbody></table><div class='history-count'><span>${rows.length} 条模拟记录 · 查询快照 11:46:20（UTC+08:00）</span>${btn('下一页','history-next','secondary','disabled title="示例记录已全部显示"')}</div></div><aside class='panel history-detail'>${sel?`<div class='row between'><h3>所选包裹</h3>${tag(sel.side==='left'?'左投递位':'右投递位','neutral')}</div><div class='barcode mono'>${sel.barcode}</div>${tag(sel.result,sel.tone)}<div class='data-pair' style='margin-top:14px'><span>本次格口</span><strong class='mono'>${sel.chute}</strong></div><ul class='timeline'><li class='success'><strong>相机读取包裹号</strong><p>${sel.time} · ${sel.side==='left'?'左位':'右位'}读码</p></li><li class='success'><strong>WCS 请求已记录</strong><p class='mono'>${sel.request}</p></li><li class='${sel.tone==='danger'?'warning':'success'}'><strong>${sel.result}</strong><p>${sel.tone==='danger'?'示例原因：包裹不在本次作业范围。':'格口与原请求对应；不代表已完成实体投递。'}</p></li></ul><details><summary>技术详情 / 原始记录</summary><pre class='code'>${esc(JSON.stringify({...sel,simulation:true},null,2))}</pre>${btn('复制所选原始记录','copy-record','ghost')}</details><div class='actions' style='margin-top:14px'>${btn('相关诊断','record-diagnostics')}${btn('支持摘要','record-support','ghost')}</div>`:`<div class='empty' style='padding:28px 8px'>${icon('history',26)}<h3>没有选中记录</h3><p>${rows.length?'请从当前查询结果中选择一条记录。':'当前筛选没有记录；清除或调整筛选后再查询。'}</p></div>`}</aside></div><div class='sim-controls'><span>原型演示</span>${btn('日期错误','history-date-error','secondary')}${btn('空记录','history-empty','secondary')}<span>筛选与详情均为模拟；列表不随新扫码跳动。</span></div>`;}
function checkRow(name,desc,state){return `<div class='check-item'><span class='${state==='success'?'ok':state==='danger'?'bad':state==='warning'?'warn':'muted'}'>${icon(state==='success'?'check':state==='danger'||state==='warning'?'alert':'clock',19)}</span><div><strong>${name}</strong><p>${desc}</p></div>${tag(state==='success'?'已通过':state==='danger'?'失败':state==='warning'?'待核对':'未执行',state)}</div>`;}
function renderDiagnostics(){const mode=S.diagnosticMode||'wcs';if(mode==='runtime')return renderRuntimeDiagnostics();const camera=mode==='left';const target=camera?'左位相机':'WCS 格口服务';const connected=camera?S.leftOnline:S.wcsOnline;const checking=S.diagnosticResult==='testing';const recovered=S.diagnosticResult==='checked'&&connected;return `<div class='page-heading'><div><h1>诊断与恢复</h1><p>先确认故障对象与影响，再执行当前允许的操作</p></div><div class='actions'>${btn('返回作业','nav-work')}${btn('导出支持摘要','record-support')}</div></div><div class='subnav'><button data-action='diagnose-wcs' class='${!camera?'active':''}'>WCS 格口服务</button><button data-action='diagnose-left' class='${camera?'active':''}'>左位相机</button><button data-action='diagnose-runtime'>配置与运行状态</button></div>${!connected?note('warning',camera?'左相机连接中断 · 仅左位受影响':'WCS 连接中断 · 左右位获取新格口受影响',camera?'右位仍可继续作业。检查左相机地址和物理连接。':'本次原请求可能已被 WCS 接收。保持原请求身份，先检查连接，再查询原结果。'):recovered?note('success','连接检查已完成 · 业务结果另行核对','模拟检查仅确认传输可达，不自动发送新业务或覆盖原请求。'):note('info',`${target} · 按层检查`,'每一层只说明本次实际检查范围。未执行的项目不显示为正常。')}<div class='diagnostic-layout'><div class='panel'><div class='row between' style='margin-bottom:13px'><h3>${target}</h3>${tag(connected?'连接可达':'连接中断',connected?'neutral':'danger')}</div><div class='scope-line'>${icon(camera?'camera':'server',18)}<code class='mono break'>${camera?`${S.runtime.left.address}:${S.runtime.left.port}`:S.runtime.wcs.url}</code><span class='spacer'></span><span class='small muted'>运行 v${S.runtimeRev}</span></div><div class='checklist' style='margin:12px 0'>${checkRow('1. 目标地址与参数','检查当前运行配置的地址格式和目标对象。','success')}${checkRow('2. 传输连接',connected?'模拟结果：目标传输端口可达。':'模拟结果：目标拒绝连接。请检查服务启动、地址及端口。',connected?'success':'danger')}${checkRow(camera?'3. 设备 SDK 连接':'3. WCS 业务接口',camera?'当前原型未调用 SDK。设备上线与真实读码需要现场验证。':'未发送测试供包请求。只有集成明确支持无业务副作用的检查接口时才执行。','neutral')}${checkRow(camera?'4. 收到有效条码':'4. 本次原请求结果',camera?'连接成功不等于已收到条码。只读观察另行验证。':S.queryStatus==='resolved'?'模拟查询已找回原请求格口 A-07；没有重新发送请求。':'本次原请求 REQ-L-0128 尚待核对。',S.queryStatus==='resolved'&&!camera?'success':!camera&&S.hasUnknown?'warning':'neutral')}</div><div class='actions'>${btn(checking?'<span class="spinner small"></span> 正在检查':`重新检查${camera?'左相机':' WCS'}连接`,'diagnostic-check','primary',checking?'disabled':'')}${btn('查看相关参数',camera?'object-left':'object-wcs')}${btn('复制技术详情','copy-diagnostic','ghost')}</div><p class='help small' style='margin-top:12px'>连接检查不保存配置、不重启服务、不重发原请求。</p></div><aside class='stack'><div class='panel'><h3>${camera?'影响与下一步':'左位原请求 · 本次包裹'}</h3>${camera?`<p class='help' style='margin:12px 0'>左位暂停接收新读码；右位是否可继续，以运行端确认的独立影响范围为准。</p><div class='data-pair'><span>右位状态</span>${tag('可继续作业','success')}</div>`:`<div class='barcode mono' style='font-size:20px;margin:15px 0'>000123456781</div><div class='data-pair'><span>请求状态</span>${tag(S.queryStatus==='resolved'?'原结果已找回':'结果待核对',S.queryStatus==='resolved'?'success':'warning')}</div><div class='data-pair'><span>原请求</span><code>REQ-L-0128</code></div><p class='help small' style='margin:12px 0'>查询原请求只核对原有结果。连接恢复后也不能直接重发这个包裹。</p>${btn(S.queryStatus==='querying'?'正在查询原请求':'查询原请求结果','query-original','primary',!connected||S.queryStatus==='querying'?'disabled title="先恢复 WCS 连接"':'')}<p class='help small' style='margin-top:9px'>原型演示集成支持查询；正式能力需核实。</p>`}</div><div class='panel'><h3>恢复判断</h3><div class='checklist'><div class='data-pair'><span>连接恢复</span>${tag(connected?'已检查':'待处理',connected?'success':'warning')}</div><div class='data-pair'><span>原请求核对</span>${tag(S.queryStatus==='resolved'?'已核对':'待核对',S.queryStatus==='resolved'?'success':'warning')}</div></div><div class='actions' style='margin-top:12px'>${btn('返回作业','nav-work')}${S.paused?btn('检查并恢复接收','resume','ghost'):''}</div></div></aside></div><div class='sim-controls'><span>原型演示</span>${btn('模拟修复连接','simulate-repair','secondary')}<span>此按钮模拟现场修复结果，正式界面不提供“一键修好网络”。</span></div>`;}
function renderRuntimeDiagnostics(){return `<div class='page-heading'><div><h1>配置与运行状态</h1><p>区分已保存、最后确认运行与当前无法确认的状态</p></div>${btn('返回配置','nav-settings-summary')}</div>${note(S.runtimeKnown?'warning':'danger',S.runtimeKnown?`应用失败后，已确认仍运行 v${S.runtimeRev}`:'运行状态无法确认 · 保持新包裹接收暂停',S.runtimeKnown?`已保存 v${S.savedRev} 保留待处理。不能把“保存成功”视为已经生效。`:'最后确认版本只能作为诊断依据。请读取当前运行端状态，不能假定自动回滚成功。')}<div class='split'><div class='panel'><h3>配置归属</h3><div style='margin-top:18px'><div class='data-pair'><span>已保存修订</span><strong>v${S.savedRev} · 待生效</strong></div><div class='data-pair'><span>最后确认运行</span><strong>v${S.runtimeRev}</strong></div><div class='data-pair'><span>本次实际运行</span>${tag(S.runtimeKnown?'已确认旧版本':'待确认',S.runtimeKnown?'warning':'danger')}</div><div class='data-pair'><span>新包裹接收</span><strong>保持暂停</strong></div></div><div class='actions' style='margin-top:18px'>${btn('重新读取运行状态','read-runtime','primary')}${btn('复制诊断信息','copy-diagnostic')}</div></div><div class='panel'><h3>允许的下一步</h3><ul class='timeline' style='margin-top:20px'><li><strong>核实每个资源实际加载版本</strong><p>相机、WCS 与工作站配置必须一致。</p></li><li><strong>处理待生效修订</strong><p>修正后再次应用，或将上一有效配置生成为新的待生效修订。</p></li><li><strong>确认恢复条件</strong><p>配置已确认、连接可用、原请求未被重复执行。</p></li></ul><div class='actions' style='margin-top:20px'>${btn('返回配置修改','object-left')}${btn('恢复上一有效配置','restore-valid')}</div></div></div>`;}

function configCandidate(){const c=clone(S.saved);if(S.drafts[S.object])c[S.object]=clone(S.drafts[S.object]);return c;}
function validateCandidate(c){const e={};for(const side of ['left','right']){const d=c[side];if(!d.name.trim())e[side+'.name']='请填写便于现场识别的设备名称。';if(!d.address.trim()||/\s/.test(d.address)||d.address.includes('://'))e[side+'.address']='请输入设备地址；不要包含协议前缀或空格。';if(!/^\d+$/.test(d.port)||Number(d.port)<1||Number(d.port)>65535)e[side+'.port']='请输入 1–65535 的整数端口，不要混用字母 O 与数字 0。';}try{const u=new URL(c.wcs.url);if(!['http:','https:'].includes(u.protocol)||!u.hostname||u.username||u.password)throw 0;}catch{e['wcs.url']='请输入完整 http:// 或 https:// 地址；凭据不要写在 URL 中。';}if(c.bindings.left===c.bindings.right){e['bindings.left']='这台相机已同时绑定右投递位，请选择不同设备。';e['bindings.right']='左右投递位不能使用同一相机实例。';}for(const k of ['queue','timeout','capacity','history']){if(!/^\d+$/.test(String(c.policies[k])))e['policies.'+k]='请填写整数；正式有效范围需由实现定义。';}return e;}
function focusFieldError(key){const input=document.getElementById('f-'+key.replace(/[^a-z0-9]/gi,'-'));if(!input)return;input.focus({preventScroll:true});const field=input.closest('.field')||input;const w=document.querySelector('.workspace');const bar=document.querySelector('.save-bar');const b=field.getBoundingClientRect();const wr=w.getBoundingClientRect();const bottom=Math.min(wr.bottom,bar?bar.getBoundingClientRect().top:wr.bottom)-12;if(b.bottom>bottom)w.scrollTop+=b.bottom-bottom;else if(b.top<wr.top+12)w.scrollTop+=b.top-wr.top-12;}
function validateConfig(thenSave=false){if(busy())return;S.errors={};S.phase='validating';render();const target=S.object;setTimeout(()=>{const candidate=configCandidate();S.errors=validateCandidate(candidate);if(Object.keys(S.errors).length){S.phase='invalid';const first=Object.keys(S.errors)[0];S.object=first.split('.')[0];render();focusFieldError(first);return;}if(S.failure==='conflict'&&thenSave){S.phase='conflict';render();return;}if(thenSave){persistCandidate(candidate,target);return;}S.phase=diff(S.drafts[S.object],S.saved[S.object]).length?'validated':pending()?'pending':'clean';render();toast('字段格式与模拟关联检查通过；尚未保存。');},500);}
function persistCandidate(candidate,target){if(!allChanges(candidate,S.saved).length){S.phase=pending()?'pending':'clean';render();toast('当前对象没有需要保存的修改。');return;}S.phase='saving';render();setTimeout(()=>{if(S.failure==='save'){S.phase='save-failed';render();return;}const changes=allChanges(candidate,S.saved);S.saved=clone(candidate);S.savedRev++;S.editBase=S.savedRev;S.drafts[target]=clone(candidate[target]);S.changeLog.unshift({rev:S.savedRev,time:'11:48:00（模拟）',object:objectNames[target],changes,reason:S.reason||'参数调整（演示）'});S.phase='pending';S.errors={};S.draftRetained=false;render();toast(`已保存 v${S.savedRev}；${S.runtimeKnown?`当前仍运行 v${S.runtimeRev}`:'当前运行版本待确认'}。`);},600);}
function reviewApply(){const changes=allChanges(S.saved,S.runtime);if(!pending()){toast('已保存值与当前运行值一致。');return;}const blocked=S.hasUnknown||!S.runtimeKnown;openDialog(`应用已保存配置 v${S.savedRev}`,`<p>本次变更 ${changes.length} 项。${S.runtimeKnown?`当前运行 v${S.runtimeRev}`:`最后确认 v${S.runtimeRev}，当前运行版本待核实`}；应用期间需要暂停整个工作站接收新包裹，并受控重启 Sportmaster。</p>${compareTable(changes)}${note('warning','影响左右两路新包裹接收','已有包裹和原请求保留。软件暂停不表示输送设备已停止；请在现场允许的维护时机执行。')}<div class='checklist'>${checkRow('运行归属',S.runtimeKnown?`运行端确认 v${S.runtimeRev}。`:'先核实运行端实际状态。',S.runtimeKnown?'success':'warning')}${checkRow('原请求已核对',S.hasUnknown?'仍有结果未知的请求，当前不能应用。':'此演示状态没有未决原请求。',S.hasUnknown?'warning':'success')}</div><div class='scope-line' style='margin-top:14px'>${icon('shield',17)}<span>维护身份校验：演示已通过；正式应用沿用现有认证机制。</span></div>`,btn('暂停接收并应用','apply-config','primary',blocked?'disabled title="先处理运行归属或未知原请求"':'')+btn('稍后应用','close-dialog'));}
function applyConfig(){if(S.hasUnknown||!S.runtimeKnown){toast('仍有阻断项，当前不能应用配置。');return;}closeDialog();S.paused=true;S.maintenance=true;S.phase='applying';render();setTimeout(()=>{S.maintenance=false;if(S.failure==='apply'||S.failure==='unknown-runtime'){S.runtimeKnown=S.failure!=='unknown-runtime';S.phase='apply-failed';S.diagnosticMode='runtime';render();return;}S.runtime=clone(S.saved);S.runtimeRev=S.savedRev;S.runtimeKnown=true;S.phase='clean';S.loginRequired=S.runtime.modules.login==='on';S.changeLog.unshift({rev:S.runtimeRev,time:'11:49:00（模拟）',object:'整个工作站',changes:[],reason:'运行端已确认生效'});render();openDialog('配置已生效',`${note('success',`运行端已确认 v${S.runtimeRev}`,'本次模拟应用完成，左右位使用已确认的运行配置。')}<p>新包裹接收仍保持暂停。确认现场准备完成后，可恢复接收；也可以继续维护。</p>`,btn('恢复接收并返回作业','finish-apply','primary')+btn('继续维护','close-dialog'));},1300);}
function testConnection(object){if(busy())return;S.test=null;const c=configCandidate();const errors=validateCandidate(c);const localErrors=Object.fromEntries(Object.entries(errors).filter(([k])=>k.startsWith(object+'.')));if(Object.keys(localErrors).length){S.errors=localErrors;S.phase='invalid';render();return;}S.test={object,phase:'testing',target:object==='wcs'?S.drafts.wcs.url:`${S.drafts[object].address}:${S.drafts[object].port}`};render();setTimeout(()=>{const ok=S.failure!=='connection'&&(object==='wcs'?S.wcsOnline:object==='left'?S.leftOnline:S.rightOnline);S.test.phase=ok?'success':'failed';render();},900);}
function setWorkScenario(name){S.scenario=name;S.snapshotFresh=true;S.wcsOnline=true;S.leftOnline=true;S.rightOnline=true;S.hasUnknown=false;S.loginRequired=false;S.loggedIn=false;S.queryStatus='idle';S.diagnosticResult='idle';S.mockRepair=false;S.left={status:'success',barcode:'000123456781',chute:'A-07',seq:128,time:'11:46:14'};S.right={status:'success',barcode:'000123456782',chute:'B-12',seq:127,time:'11:46:12'};if(name==='waiting'){S.left.status='waiting';S.right.status='waiting';}if(name==='processing')S.left.status='processing';if(name==='wcs-down'){S.wcsOnline=false;S.left.status='unknown';S.hasUnknown=true;}if(name==='camera-down'){S.leftOnline=false;S.left.status='offline';}if(name==='unknown'){S.left.status='unknown';S.right.status='rejected';S.hasUnknown=true;}if(name==='stale'){S.snapshotFresh=false;}if(name==='long'){S.left.barcode='0000123456789012345678901234567890';S.left.chute='REFERENCE-07';S.right.barcode='0000998877665544332211009988776655';S.right.chute='ZONE-EAST-00123456789';}if(name==='login')S.loginRequired=true;}
function simulateParcel(side){if(S.paused||!S.wcsOnline||!S.snapshotFresh||S.hasUnknown||S.loginRequired&&!S.loggedIn||side==='left'&&!S.leftOnline||side==='right'&&!S.rightOnline){toast('此投递位当前不满足接收条件，请先处理相应阻断项。');return;}if(S[side].status==='processing'){toast('当前包裹正在处理，请等待结果。');return;}const n=S[side].seq+2;S[side]={...S[side],seq:n,status:'processing',chute:'',barcode:'00012345'+String(6650+n),time:'11:46:'+String(n%60).padStart(2,'0')};render();setTimeout(()=>{if(S[side].seq!==n)return;S[side].status='success';S[side].chute=(side==='left'?'A-':'B-')+String(n%24+1).padStart(2,'0');if(S.view==='work')render();else document.querySelector('.status-footer').innerHTML=runtimeFooter();},1150);}
function queryOriginal(){if(!S.wcsOnline){toast('WCS 连接中断，请先恢复连接再核对原请求。');return;}if(S.queryStatus==='querying')return;const seq=S.left.seq;S.queryStatus='querying';render();toast('正在查询原请求 REQ-L-0128；不会重发供包请求。');setTimeout(()=>{S.queryStatus='resolved';if(S.left.seq===seq){S.left.status='success';S.left.chute='A-07';S.hasUnknown=false;}render();openDialog('已找回原请求的结果',`${note('success','左投递位 · 本次格口 A-07','模拟查询确认原请求结果；没有创建新的供包请求。')}<div class='data-pair'><span>包裹号</span><code>000123456781</code></div><div class='data-pair'><span>原请求</span><code>REQ-L-0128</code></div><p style='margin-top:15px'>核对现场包裹仍为该原件后，按当前结果处理。若对应包裹已变化，本结果只保留在原记录中。</p>`,btn('返回作业','query-return','primary')+btn('继续查看诊断','close-dialog'));},950);}
function checkResume(){if(!S.runtimeKnown||S.hasUnknown||!S.snapshotFresh||!S.wcsOnline||S.maintenance){openDialog('暂不能恢复接收',`${note('warning','仍有运行阻断项','请先核实运行配置、状态来源、WCS 连接或原请求结果。')}<p>当前包裹与历史记录保留，不会自动清除或重新发送。</p>`,btn('进入诊断','resume-diagnose','primary')+btn('保持暂停','close-dialog'));return;}if(S.loginRequired&&!S.loggedIn){operatorLogin();return;}openDialog('恢复接收新包裹',`<p>将恢复示例工作站 17 的软件接收。已有请求保持原身份；此操作不控制输送设备。</p><div class='data-pair'><span>当前运行配置</span><strong>v${S.runtimeRev}</strong></div><div class='data-pair'><span>原请求未决项</span><strong>无（模拟）</strong></div>`,btn('恢复接收','resume-confirm','primary')+btn('保持暂停','close-dialog'));}
function operatorLogin(){openDialog('操作员登录 · 模拟场景',`<p>仅在本站启用操作员登录时出现。本原型不校验真实凭据，请勿输入真实口令。</p><div class='stack'>${field('操作员账号','login-demo-user','演示操作员','此身份用于演示随扫码记录的操作员信息。',{readonly:true})}${field('口令','login-demo-password','••••••••','演示占位，不接收真实口令。',{readonly:true})}</div>`,btn('模拟登录成功','login-success','primary')+btn('返回','close-dialog'));}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('已复制模拟技术详情。');}catch{openDialog('复制技术详情',`<p>请选择下方文本复制；浏览器未授权直接访问剪贴板。</p><textarea class='code' readonly style='width:100%;height:210px'>${esc(t)}</textarea>`,btn('关闭','close-dialog'));}}
function restoreValid(){if(!S.runtimeKnown){toast('当前运行版本未知，先核实上一有效配置来源。');return;}openDialog('恢复上一有效配置',`<p>将最后确认的运行配置 v${S.runtimeRev} 复制为新的待生效修订。此操作只恢复整站配置，不回滚包裹记录、业务请求或已安装驱动。</p>${compareTable(allChanges(S.saved,S.runtime))}${note('warning','恢复后仍需受控应用','不会自动重新发送请求，也不会自动恢复接收。')}`,btn('生成恢复修订','restore-valid-confirm','primary')+btn('取消','close-dialog'));}
function editField(key,value){if(key.startsWith('aux.')){if(typeof auxField==='function')auxField(key,value);return;}if(key==='demo-scene'){setWorkScenario(value);render();return;}if(key==='demo-failure'){S.failure=value;return;}if(key==='preference-motion'){S.reduceMotion=!!value;document.body.style.setProperty('--motion',S.reduceMotion?'0s':'.1s');const style=document.getElementById('reduced-style')||Object.assign(document.createElement('style'),{id:'reduced-style'});style.textContent=S.reduceMotion?'*{animation:none!important;transition:none!important}':'';if(!style.isConnected)document.head.appendChild(style);toast('显示偏好已即时更新；运行配置未改变。');return;}if(key.startsWith('history.')){const k=key.split('.')[1];if(k==='request')S.historyRequest=value;else S.historyFilters[k]=value;if(k==='range')render();return;}if(key==='history-start'){S.historyDateStart=value;return;}if(key==='history-end'){S.historyDateEnd=value;return;}const [o,k]=key.split('.');if(S.drafts[o]&&Object.hasOwn(S.drafts[o],k)){S.drafts[o][k]=value;S.phase='dirty';S.draftRetained=false;S.test=null;const bar=document.getElementById('save-bar');if(bar)bar.outerHTML=saveBar();const rev=document.querySelector('.revision-bar');if(rev)rev.outerHTML=revisionBar();}}
function handleAction(action,el){if(!action||el?.disabled)return;if(action==='close-dialog'){closeDialog();return;}if(action.startsWith('nav-')){const parts=action.slice(4).split('-');if(parts[0]==='diagnostics'&&S.phase==='apply-failed')S.diagnosticMode='runtime';go(parts[0],parts[1]);return;}if(action.startsWith('object-')){go('settings',action.slice(7));return;}if(action==='toggle-tray'){S.tray=!S.tray;renderTray();return;}if(action==='reset-demo'){closeDialog();location.href=location.href.split('?')[0].split('#')[0];return;}if(action==='scene-camera-invalid'){setScene('camera-invalid');return;}if(action==='undo'){S.drafts[S.object]=clone(S.saved[S.object]);S.errors={};S.phase=pending()?'pending':'clean';S.test=null;render();toast('当前对象已还原为已保存值；运行配置未改变。');return;}if(action==='validate'){validateConfig(false);return;}if(action==='save'){validateConfig(true);return;}if(action==='review-apply'){reviewApply();return;}if(action==='apply-config'){applyConfig();return;}if(action==='finish-apply'){closeDialog();if(S.loginRequired&&!S.loggedIn){S.view='work';render();operatorLogin();return;}S.paused=false;S.view='work';render();toast('配置已生效，已恢复接收新包裹（模拟）。');return;}if(action==='restore-valid'){restoreValid();return;}if(action==='restore-valid-confirm'){closeDialog();S.saved=clone(S.runtime);S.drafts=clone(S.saved);S.savedRev++;S.editBase=S.savedRev;S.phase='pending';S.changeLog.unshift({rev:S.savedRev,time:'11:50:00（模拟）',object:'整个工作站',reason:'从上一有效运行配置生成恢复修订',changes:[]});render();toast('已生成恢复修订；仍需受控应用。');return;}if(action==='compare-conflict'){openDialog('比较当前修订冲突',`<p>模拟另一处修改已更新配置基线。你的编辑全部保留；此原型不自动合并真实配置。</p>${compareTable(allChanges(S.drafts,S.saved))}<p class='small muted' style='margin-top:15px'>正式客户端需读取最新修订，逐项决定保留哪个值，再重新校验完整候选。</p>`,btn('模拟采用新基线并保留编辑','conflict-rebase','primary')+btn('返回编辑','close-dialog'));return;}if(action==='conflict-rebase'){S.editBase=S.savedRev;S.failure='none';S.phase='dirty';closeDialog();render();toast('模拟基线核对完成，编辑已保留；尚未保存。');return;}if(action==='unsaved-keep'||action==='unsaved-discard'){if(action==='unsaved-keep'){S.draftRetained=true;if(typeof auxKeepDraft==='function')auxKeepDraft();}else{S.drafts=clone(S.saved);S.errors={};S.draftRetained=false;if(typeof auxDiscardChanges==='function')auxDiscardChanges();}const target=S.pendingNav;closeDialog();S.pendingNav=null;if(target){S.view=target.view;if(target.object)S.object=target.object;}S.phase=dirty()?'dirty':pending()?'pending':'clean';render();return;}if(action==='test-camera'||action==='test-wcs'){testConnection(S.object);return;}if(action==='focus-connection'){document.getElementById('f-'+S.object+'-'+(S.object==='wcs'?'url':'port'))?.focus();return;}if(action==='copy-test'){copyText(JSON.stringify({...S.test,simulation:true,saved:false,applied:false,businessRequestSent:false},null,2));return;}if(action==='test-detail'){openDialog('本次连接检查范围',`${checkRow('地址与格式','当前编辑值的目标格式。','success')}${checkRow('传输连接','模拟连接可达。','success')}${checkRow('设备数据 / 业务响应','未采集、不发送供包请求。','neutral')}<p class='small muted'>结果仅描述测试范围，不能视为真实现场资格通过。</p>`,btn('关闭','close-dialog'));return;}if(action==='simulate-left'||action==='simulate-right'){simulateParcel(action.slice(9));return;}if(action==='pause'){openDialog('暂停接收新包裹',`<p>暂停当前工作站的左右位新入场。已创建的请求、回执和本次结果保持；相机可能继续读码，软件不会据此创建新入场。</p>${note('warning','此操作不停止输送设备','不是安全急停；请按现场操作规程处理实体设备。')}`,btn('暂停接收','pause-confirm','primary')+btn('取消','close-dialog'));return;}if(action==='pause-confirm'){closeDialog();S.paused=true;render();return;}if(action==='resume'){checkResume();return;}if(action==='resume-confirm'){closeDialog();S.paused=false;S.view='work';render();return;}if(action==='resume-diagnose'){closeDialog();S.view='diagnostics';render();return;}if(action==='operator-login'){operatorLogin();return;}if(action==='login-success'){closeDialog();S.loggedIn=true;render();toast('模拟操作员已登录；维护阻断项仍单独判断。');return;}if(action==='query-original'){queryOriginal();return;}if(action==='query-return'){closeDialog();S.view='work';render();return;}if(action==='rejection-detail'){openDialog('右投递位 · WCS 拒绝本次包裹',`<div class='data-pair'><span>包裹号</span><code>${esc(S.right.barcode)}</code></div>${note('danger','示例原因：包裹不在当前作业范围','本次没有有效格口。保留原件，核对上游任务或联系负责人员。')}<p>此处不提供通用“重发”按钮。重新处理的条件须由本 WCS 协议和现场流程明确。</p>`,btn('查看原记录','rejection-record','primary')+btn('返回作业','close-dialog'));return;}if(action==='rejection-record'){closeDialog();S.historySelection=3;S.view='history';render();return;}if(action.startsWith('current-')){const side=action.slice(8),r=S[side];openDialog(`${side==='left'?'左':'右'}投递位 · 本次包裹`,`${note('success',`本次格口 ${esc(r.chute)}`,'这是取得格口的结果，不等于实体投递已经完成。')}<div class='data-pair'><span>包裹号</span><code>${esc(r.barcode)}</code></div><div class='data-pair'><span>本次序号</span><strong>#${r.seq}</strong></div><div class='data-pair'><span>对应投递位</span><strong>${side==='left'?'左':'右'}投递位</strong></div><div class='data-pair'><span>观测时间</span><code>${r.time} +08:00</code></div>`,btn('查看记录','dialog-history')+btn('返回作业','close-dialog'));return;}if(action==='dialog-history'){closeDialog();S.view='history';render();return;}if(action.startsWith('record-')&&/^record-\d+$/.test(action)){S.historySelection=Number(action.slice(7));go('history');return;}if(action.startsWith('select-record-')){S.historySelection=Number(action.slice(14));render();return;}if(action==='query-history'){if(S.historyFilters.range==='custom'&&(!S.historyDateStart||!S.historyDateEnd||S.historyDateStart>S.historyDateEnd)){S.historyError='开始日期不能晚于结束日期，且两个日期都需填写。';render();document.getElementById('f-history-start')?.focus();return;}S.historyError='';render();toast('已更新模拟查询快照；新扫码不会使此列表跳动。');return;}if(action==='history-advanced'){S.historyAdvanced=!S.historyAdvanced;render();return;}if(action==='history-date-error'){S.historyFilters.range='custom';S.historyDateStart='2026-10-21';S.historyDateEnd='2026-10-20';S.historyError='开始日期晚于结束日期，请修正开始日期。';render();return;}if(action==='history-empty'){S.historyFilters.barcode='NO-MATCH';render();return;}if(action==='clear-history'){S.historyFilters={barcode:'',side:'all',result:'all',range:'today'};S.historyError='';render();return;}if(action==='export-history'){const rows=filteredHistory();const csv='\uFEFF时间（UTC+08:00）,投递位,包裹号,处理结果,格口\r\n'+rows.map(r=>[r.time,r.side==='left'?'左位':'右位',r.barcode,r.result,r.chute].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadText('sportmaster-demo-records.csv',csv,'text/csv;charset=utf-8');toast('已导出当前筛选的模拟记录；CSV 保留原条码字符。');return;}if(action==='copy-record'){copyText(JSON.stringify({...HISTORY[S.historySelection],simulation:true},null,2));return;}if(action==='record-diagnostics'){S.diagnosticMode='wcs';go('diagnostics');return;}if(action==='record-support'||action==='support-config'){go('support');return;}if(action.startsWith('diagnose-')){S.diagnosticMode=action.slice(9)==='wcs'?'wcs':action.slice(9)==='left'?'left':'runtime';go('diagnostics');return;}if(action==='diagnostic-check'){S.diagnosticResult='testing';render();setTimeout(()=>{if(S.mockRepair){if(S.diagnosticMode==='left')S.leftOnline=true;else S.wcsOnline=true;}S.diagnosticResult='checked';render();toast('模拟分层检查完成；未发送业务请求。');},950);return;}if(action==='simulate-repair'){S.mockRepair=true;toast('已模拟现场修复。请点击重新检查连接，读取检查结果。');return;}if(action==='copy-diagnostic'){copyText(JSON.stringify({simulation:true,target:S.diagnosticMode||'wcs',wcsOnline:S.wcsOnline,runtimeRevision:S.runtimeKnown?S.runtimeRev:'unknown',lastConfirmedRuntime:S.runtimeRev,savedRevision:S.savedRev,originalRequest:'REQ-L-0128',queryStatus:S.queryStatus},null,2));return;}if(action==='read-runtime'){S.runtimeKnown=true;S.paused=true;render();toast(`模拟重新读取完成：实际运行 v${S.runtimeRev}，仍保持暂停。`);return;}if(action==='choose-driver'){openDialog('为当前设备选择驱动',`<p>驱动决定可用参数。设备实例和投递位绑定分别管理；更换驱动后必须重新校验。</p><div class='list-row'>${icon('camera',20)}<div><strong>相机读码 · 演示适配器</strong><p class='help small'>版本 1.0（示例） · 当前选择</p></div><span class='spacer'></span>${tag('已选择','info')}</div><div class='list-row'><div><strong>其他相机驱动</strong><p class='help small'>需从交付介质安装，真实驱动与 SDK 版本待核实。</p></div></div>`,btn('查看组件安装','driver-install')+btn('保留当前选择','close-dialog'));return;}if(action==='driver-install'){closeDialog();go('install');return;}if(action==='install-component'){go('install');return;}if(action==='component-json'){openDialog('组件技术清单 · 截图已知字段',`<p>这些键用于维护诊断。它们不是本 Sportmaster 界面需要逐项填写的业务字段。</p><pre class='code'>Providers\n  Kind / Implementation / Version / Contract\n  Parameters\n  Requirements\n    MeasuredWeight / ImageAddress / Query / PhysicalConfirmation</pre><p class='help small'>截图未展开的参数不在此补造。</p>`,btn('关闭','close-dialog'));return;}if(action==='maintenance-auth'){openDialog('维护身份 · 演示',`<p>维护账号与口令采用现有认证机制。原型不收集真实凭据。</p>${field('维护账号','demo-maintenance','maintenance','来自原截图的账号示例。',{readonly:true})}<p class='help small' style='margin-top:12px'>生产客户端需验证会话有效性与操作范围，而不因进入设置页面要求操作员强制登录。</p>`,btn('模拟认证通过','maintenance-success','primary')+btn('返回','close-dialog'));return;}if(action==='maintenance-success'){closeDialog();toast('模拟维护认证通过；不代表真实权限验证。');return;}if(action==='backup-history'){if(typeof auxState==='function')auxState().backup.tab='history';go('backup');return;}if(typeof auxAction==='function'&&auxAction(action,el))return;toast('此演示操作尚未启用，请查看交接说明中的实现依赖。');}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)handleAction(el.dataset.action,el);});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('input[data-field],textarea[data-field]'))editField(el.dataset.field,el.type==='checkbox'?el.checked:el.value);});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('select[data-field]'))editField(el.dataset.field,el.value);});
document.addEventListener('keydown',e=>{const modal=document.querySelector('.modal');if(e.key==='Escape'&&modal){e.preventDefault();closeDialog();return;}if(e.key==='Tab'&&modal){const focusable=[...modal.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(e.key==='Enter'&&e.target.matches('tr[data-action]')){e.preventDefault();handleAction(e.target.dataset.action,e.target);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(S.view==='settings'&&dirty())validateConfig(true);}});
window.addEventListener('beforeunload',e=>{if(dirty()||typeof auxHasUnsaved==='function'&&auxHasUnsaved()){e.preventDefault();e.returnValue='';}});
